async fn total(id: &str) -> i32 {
    match id {
        "o1" => 2500,
        "o2" => 7500,
        _ => 0,
    }
}

#[tokio::main]
async fn main() {
    let left = tokio::spawn(total("o1"));
    let right = tokio::spawn(total("o2"));
    let local = total("o3").await;
    let (first, second) = tokio::join!(left, right);
    println!("{}", local + first.unwrap() + second.unwrap());
}
